@app.get("/dolar")
def get_all_dolar_rates():
    return {
        "api_version": "v1",
        "total_records": len(DOLAR_DATABASE),
        "data": DOLAR_DATABASE
    }


@app.get("/dolar/{id}")
def get_dolar_by_id(id: str):
    record = next((item for item in DOLAR_DATABASE if item["id"] == id), None)
    if not record:
        raise HTTPException(
            status_code=404, 
            detail=f"No se encontró registro del tipo de cambio para el ID/fecha: '{id}'"
        )
    return record
